@import url(chrome://calendar/skin/shared/calendar-unifinder.css);

/* restyle splitter-border to match Thunderbird's layout */
#calendar-view-splitter {
  appearance: none;
  border-block-end: 1px solid var(--sidebar-border);
  /* splitter grip area */
  block-size: 5px;
  /* make only the splitter border visible */
  margin-block-start: -5px;
  /* because of the negative margin needed to make the splitter visible */
  position: relative;
  z-index: 10;
}

#bottom-events-box {
  border-inline-start: 1px solid ThreeDShadow;
}

/* added for new id ..... search box ..... */
#unifinder-searchBox {
  background-color: transparent;
  border-block-end: 1px solid ThreeDShadow;
  block-size: 1.5em;
  min-block-size: 35px;
}

.unifinder-closebutton {
  margin-inline-end: 2px;
}
